blocks.code:
// polling
ADC_CTRL = CH3 | START
while (ADC_STATUS & EOC) == 0:
    ;                       // wait
code = ADC_DATA
ADC_STATUS = EOC            // clear flag

// interrupt
ADC_CTRL = CH3 | START | ADC_INT_EN
// ISR when EOC sets:
isr_adc():
    code = ADC_DATA
    ADC_STATUS = EOC
    done = 1
